local _, WFJ = ...
WFJ.Data.add("book", {
  ["6a0f16a491e5f3b3"] = { "Studio delle discipline\n\nGnomi e goblin proteggono le loro conoscenze gli uni dagli altri a tal punto che è quasi impossibile accedere a entrambe le discipline contemporaneamente. Ciascuna razza, a prescindere dalle affiliazioni politiche, rende disponibili le conoscenze della propria disciplina solo a chi accetta di rinunciare allo studio della disciplina rivale. Se uno studente sceglie di abbracciare l'ingegneria gnomesca, per esempio, nessuna conoscenza dell'ingegneria goblin gli sarà mai resa disponibile.", "." },
  ["6a39ef6de25a13e0"] = { "Nobile signore,\n\nla notizia che cercate un precettore per i vostri figli è giunta fino a me qui a ⟦Goldshire=Borgodoro⟧, dove risiedo temporaneamente alla Lion's Pride Inn. A causa dei tristi eventi che hanno colpito la regione, sono stato costretto ad abbandonare il mio incarico di preside della scuola di ⟦Moonbrook=Rivoluna⟧. Vi prego di accettare la mia candidatura a precettore della vostra prole. Il preside Crillian dell'Accademia potrà parlarvi delle mie capacità, se necessario.", "." },
  ["6ab6d34b6f3a3106"] = { "La sorte di Marduk Pozzanera\n\nMarduk sopravvisse alla Seconda Guerra, seminando morte e sofferenza con la sua spada immonda, coperta di rune. Benché Marduk sia ancora vivo, la sua spada andò perduta in una battaglia nei pressi del ⟦Corin's Crossing=Crocevia di Corin⟧. Un capitano nano frantumò la spada sul suo scudo incantato, costringendo Marduk a fuggire dal campo e assicurando la vittoria all'⟦Alliance=Alleanza⟧.\n\nLa spada di Marduk sprofondò nella terra e la corruppe, scavando nel suolo una gola oggi nota come Cicatrice Infetta.", "." },
  ["6ad16335ece85f87"] = { "Domare le bestie, tirare da maestro, seguire le tracce come un esperto: cos'altro vuoi realizzare in questa vita? Tutte queste cose insieme richiedono parecchia intelligenza e una gran dose di pazienza.\n\nLa via del cacciatore non è facile, questo è certo. Ti servirà un sacco di addestramento se vuoi valere anche solo quanto il più umile dei nostri fucilieri. Ma è per questo che sono qui.\n\nCercami dentro ⟦Anvilmar=Forgiamara⟧, che domina la ⟦Coldridge Valley=Valle Crestafredda⟧. Ti aspetto.\n\n-Thorgas Grimson, istruttore dei cacciatori", "." },
  ["6aedeade911d13b0"] = { "I clan orcheschi dispersi furono presto radunati e rinchiusi in campi di internamento sorvegliati. Benché sembrasse che l'⟦Horde=Orda⟧ fosse stata sconfitta per sempre, alcuni dubitavano fortemente che la pace sarebbe durata. Khadgar, ormai un arcimago di una certa fama, convinse l'alto comando dell'⟦Alliance=Alleanza⟧ a costruire la fortezza di ⟦Nethergarde=Guardiafatua⟧, che avrebbe vegliato sulle rovine del Portale Oscuro e garantito che non vi sarebbero state altre invasioni da Draenor.", "." },
  ["6af27a6d399249e4"] = { "<HTML>\n<BODY>\n<H1 align=\"center\">\nSCHEMA DEL PILASTRO SETTENTRIONALE\n</H1>\n<BR/>\n<IMG src=\"Interface\\Pictures\\11482_crystals_north\"/>\n</BODY>\n</HTML>", "." },
})
